package com.gratilo.user.controller;
import io.micronaut.context.annotation.Requires;
import com.gratilo.user.api.PoolResponses; import com.gratilo.user.service.PoolService; import io.micronaut.http.*; import io.micronaut.http.annotation.*; import io.micronaut.security.annotation.Secured; import io.micronaut.security.rules.SecurityRule; import java.util.UUID;
@Secured(SecurityRule.IS_ANONYMOUS) @Requires(property = "features.tip-pools-enabled", value = "true")
@Controller("/user-service/internal/pools") public class PoolDistributionController { private final PoolService service; public PoolDistributionController(PoolService service){this.service=service;} @Get("/{ownerId}") public HttpResponse<?> distribution(UUID ownerId,@Header("X-Internal-Secret") String secret,@io.micronaut.context.annotation.Value("${internal.api-key}") String expected){if(secret==null||!secret.equals(expected))return HttpResponse.unauthorized();var result=service.distribution(ownerId);return result==null?HttpResponse.notFound():HttpResponse.ok(result);} }
